        std::ostringstream oss;
        oss << "Cat007I130_sub{";
        bool first = true;
        if (srl_.has_value()) {
            if (!first) oss << ", ";
            first = false;
            oss << "srl=" << static_cast<uint64_t>(*srl_);
        }
