    uint8_t& mutable_nucpNic() { return nucpNic_; }
    void set_nucpNic(const uint8_t& v) { nucpNic_ = v; }

    bool has_nicBaro() const { return nicBaro_.has_value(); }
    const uint8_t& nicBaro() const { return nicBaro_.value(); }
    uint8_t& mutable_nicBaro() { if (!nicBaro_) nicBaro_.emplace(); return *nicBaro_; }
    void set_nicBaro(const uint8_t& v) { nicBaro_ = v; }
    void clear_nicBaro() { nicBaro_.reset(); }

    bool has_sil() const { return sil_.has_value(); }
    const uint8_t& sil() const { return sil_.value(); }
    uint8_t& mutable_sil() { if (!sil_) sil_.emplace(); return *sil_; }
    void set_sil(const uint8_t& v) { sil_ = v; }
    void clear_sil() { sil_.reset(); }

    bool has_nacp() const { return nacp_.has_value(); }
    const uint8_t& nacp() const { return nacp_.value(); }
    uint8_t& mutable_nacp() { if (!nacp_) nacp_.emplace(); return *nacp_; }
    void set_nacp(const uint8_t& v) { nacp_ = v; }
    void clear_nacp() { nacp_.reset(); }

    bool has_sils() const { return sils_.has_value(); }
    const uint8_t& sils() const { return sils_.value(); }
    uint8_t& mutable_sils() { if (!sils_) sils_.emplace(); return *sils_; }
    void set_sils(const uint8_t& v) { sils_ = v; }
    void clear_sils() { sils_.reset(); }

    bool has_sda() const { return sda_.has_value(); }
    const uint8_t& sda() const { return sda_.value(); }
    uint8_t& mutable_sda() { if (!sda_) sda_.emplace(); return *sda_; }
    void set_sda(const uint8_t& v) { sda_ = v; }
    void clear_sda() { sda_.reset(); }

    bool has_gva() const { return gva_.has_value(); }
    const uint8_t& gva() const { return gva_.value(); }
    uint8_t& mutable_gva() { if (!gva_) gva_.emplace(); return *gva_; }
    void set_gva(const uint8_t& v) { gva_ = v; }
    void clear_gva() { gva_.reset(); }

    bool has_pic() const { return pic_.has_value(); }
    const uint8_t& pic() const { return pic_.value(); }
    uint8_t& mutable_pic() { if (!pic_) pic_.emplace(); return *pic_; }
    void set_pic(const uint8_t& v) { pic_ = v; }
    void clear_pic() { pic_.reset(); }

    bool operator==(const Cat021I090&) const = default;

    conduit::VoidResult encode(conduit::io::BitWriter& w) const {
        w.write_bits(nucrNacv_, 3);
        w.write_bits(nucpNic_, 4);
        {
            bool fx_continue = false;
            if (nicBaro_.has_value()) fx_continue = true;
            if (sil_.has_value()) fx_continue = true;
            if (nacp_.has_value()) fx_continue = true;
            if (sils_.has_value()) fx_continue = true;
            if (sda_.has_value()) fx_continue = true;
            if (gva_.has_value()) fx_continue = true;
            if (pic_.has_value()) fx_continue = true;
            w.write_bits(fx_continue ? 1 : 0, 1);
            if (fx_continue) {
                w.write_bits(nicBaro_.value_or(0), 1);
                w.write_bits(sil_.value_or(0), 2);
                w.write_bits(nacp_.value_or(0), 4);
                {
                    bool fx_continue_1 = false;
                    if (sils_.has_value()) fx_continue_1 = true;
                    if (sda_.has_value()) fx_continue_1 = true;
                    if (gva_.has_value()) fx_continue_1 = true;
                    if (pic_.has_value()) fx_continue_1 = true;
                    w.write_bits(fx_continue_1 ? 1 : 0, 1);
                    if (fx_continue_1) {
                        w.write_bits(0, 2);
                        w.write_bits(sils_.value_or(0), 1);
                        w.write_bits(sda_.value_or(0), 2);
                        w.write_bits(gva_.value_or(0), 2);
                        {
                            bool fx_continue_2 = false;
                            if (pic_.has_value()) fx_continue_2 = true;
                            w.write_bits(fx_continue_2 ? 1 : 0, 1);
                            if (fx_continue_2) {
                                w.write_bits(pic_.value_or(0), 4);
                                w.write_bits(0, 3);
                                w.write_bits(0, 1); // Terminal FX=0
                            }
                        }
                    }
                }
            }
        }
        if (w.has_error()) return std::unexpected(w.error());
        return {};
    }

    static conduit::Result<Cat021I090> decode(conduit::io::BitReader& r) {
        Cat021I090 result;
        {
            auto val = r.read_bits(3);
            if (!val) return std::unexpected(val.error().with_context("decode Cat021I090.nucrNacv"));
            result.nucrNacv_ = static_cast<uint8_t>(*val);
        }
        {
            auto val = r.read_bits(4);
            if (!val) return std::unexpected(val.error().with_context("decode Cat021I090.nucpNic"));
            result.nucpNic_ = static_cast<uint8_t>(*val);
        }
        // FX extension
        {
            auto fx_bit = r.read_bits(1);
            if (!fx_bit) return std::unexpected(fx_bit.error());
            if (*fx_bit) {
                {
                    auto val = r.read_bits(1);
                    if (!val) return std::unexpected(val.error());
                    result.nicBaro_ = static_cast<uint8_t>(*val);
                }
                {
                    auto val = r.read_bits(2);
                    if (!val) return std::unexpected(val.error());
                    result.sil_ = static_cast<uint8_t>(*val);
                }
                {
                    auto val = r.read_bits(4);
                    if (!val) return std::unexpected(val.error());
                    result.nacp_ = static_cast<uint8_t>(*val);
                }
                // FX extension
                {
                    auto fx_bit_1 = r.read_bits(1);
                    if (!fx_bit_1) return std::unexpected(fx_bit_1.error());
                    if (*fx_bit_1) {
                        CONDUIT_TRY(r.skip_bits(2));
                        {
                            auto val = r.read_bits(1);
                            if (!val) return std::unexpected(val.error());
                            result.sils_ = static_cast<uint8_t>(*val);
                        }
                        {
                            auto val = r.read_bits(2);
                            if (!val) return std::unexpected(val.error());
                            result.sda_ = static_cast<uint8_t>(*val);
                        }
                        {
                            auto val = r.read_bits(2);
                            if (!val) return std::unexpected(val.error());
                            result.gva_ = static_cast<uint8_t>(*val);
                        }
                        // FX extension
                        {
                            auto fx_bit_2 = r.read_bits(1);
                            if (!fx_bit_2) return std::unexpected(fx_bit_2.error());
                            if (*fx_bit_2) {
                                {
                                    auto val = r.read_bits(4);
                                    if (!val) return std::unexpected(val.error());
                                    result.pic_ = static_cast<uint8_t>(*val);
                                }
                                CONDUIT_TRY(r.skip_bits(3));
                                CONDUIT_TRY(r.skip_bits(1)); // Terminal FX=0
                            }
                        }
                    }
                }
            }
        }
        return result;
    }

    std::string to_string(std::span<const std::pair<std::string, std::string>> overrides) const {
        (void)overrides;
        std::ostringstream oss;
        oss << "Cat021I090{"
            << "nucrNacv=" << +(nucrNacv_)
            << ", nucpNic=" << +(nucpNic_)
            << ", nicBaro=" << (nicBaro_.has_value() ? std::to_string(*nicBaro_) : std::string("<none>"))
            << ", sil=" << (sil_.has_value() ? std::to_string(*sil_) : std::string("<none>"))
            << ", nacp=" << (nacp_.has_value() ? std::to_string(*nacp_) : std::string("<none>"))
            << ", sils=" << (sils_.has_value() ? std::to_string(*sils_) : std::string("<none>"))
            << ", sda=" << (sda_.has_value() ? std::to_string(*sda_) : std::string("<none>"))
            << ", gva=" << (gva_.has_value() ? std::to_string(*gva_) : std::string("<none>"))
            << ", pic=" << (pic_.has_value() ? std::to_string(*pic_) : std::string("<none>"))
            << "}";
        return oss.str();
    }
    std::string to_string() const { return to_string({}); }

private:
    uint8_t nucrNacv_{};
    uint8_t nucpNic_{};
    std::optional<uint8_t> nicBaro_;
    std::optional<uint8_t> sil_;
    std::optional<uint8_t> nacp_;
    std::optional<uint8_t> sils_;
