// I253/090 - Application Data (not used, included for completeness)
class Cat253I090 {
public:
    const uint8& rep() const { return rep_; }
    uint8& mutable_rep() { return rep_; }
    void set_rep(const uint8& v) { rep_ = v; }

    const std::vector<Cat253I090_dataItemsElement>& dataItems() const { return dataItems_; }
    std::vector<Cat253I090_dataItemsElement>& mutable_dataItems() { return dataItems_; }
    void set_dataItems(const std::vector<Cat253I090_dataItemsElement>& v) { dataItems_ = v; }

    bool operator==(const Cat253I090&) const = default;

    conduit::VoidResult encode(conduit::io::BitWriter& w) const {
        w.write_u8(static_cast<uint8>(dataItems_.size()));
        for (const auto& elem : dataItems_) {
            CONDUIT_TRY(elem.encode(w));
        }
        if (w.has_error()) return std::unexpected(w.error());
        return {};
    }

    static conduit::Result<Cat253I090> decode(conduit::io::BitReader& r) {
        Cat253I090 result;
        {
            auto val = r.read_u8();
            if (!val) return std::unexpected(val.error().with_context("decode Cat253I090.rep"));
            result.rep_ = static_cast<uint8>(*val);
        }
        {
            auto count = static_cast<size_t>(result.rep_);
            if (count > static_cast<size_t>(INT32_MAX)) return std::unexpected(conduit::Error(conduit::ErrorCode::InvalidArgument, "decode Cat253I090.dataItems: decoded count " + std::to_string(count) + " exceeds INT32_MAX").with_context("decode Cat253I090.dataItems"));
            result.dataItems_.reserve(count);
            for (size_t i = 0; i < count; i++) {
                auto elem = Cat253I090_dataItemsElement::decode(r);
                if (!elem) return std::unexpected(elem.error().with_context("decode Cat253I090.dataItems"));
                result.dataItems_.push_back(std::move(*elem));
            }
        }
        return result;
    }

    std::string to_string(std::span<const std::pair<std::string, std::string>> overrides) const {
        (void)overrides;
        std::ostringstream oss;
        oss << "Cat253I090{"
            << "rep=" << +(rep_)
            << ", dataItems=["
            ;
            for (size_t i = 0; i < dataItems_.size(); ++i) {
                if (i > 0) oss << ", ";
                oss << dataItems_[i].to_string();
            }
            oss << "]"
            << "}";
        return oss.str();
    }
    std::string to_string() const { return to_string({}); }

private:
    uint8 rep_{};
    std::vector<Cat253I090_dataItemsElement> dataItems_{};
};

